import heapq


def _ledger(data, revision_first, original_tax, refunds):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if revision_first:
            key = (event.get("revision", 0), position)
        else:
            key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax_base = raw if original_tax else net
        tax = rounded(tax_base * event.get("tax_bp", 0))
        amount = net + tax
        if refunds and event.get("kind") == "refund":
            amount = -amount
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    roots = data["roots"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    choices = []
    for name in names:
        allowed = [row["version"] for row in packages[name]
                   if row["version"] not in blocked.get(name, [])
                   and (name not in pins or row["version"] == pins[name])]
        choices.append([-1] + allowed)

    best_vector = None
    best_installation = None
    for vector in product(*choices):
        installed = {name: version for name, version in zip(names, vector)
                     if version != -1}
        if any(name not in installed or
               not low <= installed[name] <= high
               for name, (low, high) in roots.items()):
            continue

        graph = {name: [] for name in installed}
        valid = True
        for name, version in installed.items():
            row = next(row for row in packages[name]
                       if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in installed or
                        not dep["min"] <= installed[target] <= dep["max"]):
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            pending.extend(graph[name])
        if reachable != set(installed):
            continue

        active, finished = set(), set()

        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(child) for child in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in graph):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = installed

    if best_installation is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _jobs(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in data["jobs"] if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = maximum = 0
        for _, delta in sorted(events):
            active += delta
            maximum = max(maximum, active)
        if maximum > 2:
            continue

        value = sum(job["value"] for job in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    indexes = {node: index for index, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    start_mask = 1 << indexes[source] if source in indexes else 0
    start_state = (source, start_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": time}

        for edge in graph[node]:
            departure = max(time, edge["open"])
            if departure >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))

            for duration, next_remaining in choices:
                arrival = departure + duration
                if arrival > data["deadline"]:
                    continue
                destination = edge["v"]
                next_mask = mask
                if destination in indexes:
                    next_mask |= 1 << indexes[destination]
                next_state = (destination, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, destination, next_mask,
                                           next_remaining))

    return {"arrival": None}


